import{z as l,x as o,o as n,c as A,q as t,j as s,D as a,d as i,s as B,S as d,b as r}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"市场与融资流动性 Brunnermeier–Pedersen","description":"","frontmatter":{"title":"市场与融资流动性 Brunnermeier–Pedersen","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/market-funding-liquidity.md","filePath":"econ/market-funding-liquidity.md","lastUpdated":1791413859000}'),p={name:"econ/market-funding-liquidity.md"};function u(m,e,h,c,D,f){const E=o("Mermaid");return n(),A("div",null,[e[2]||(e[2]=t('<h1 id="市场与融资流动性-brunnermeier–pedersen" tabindex="-1">市场与融资流动性 Brunnermeier–Pedersen <a class="header-anchor" href="#市场与融资流动性-brunnermeier–pedersen" aria-label="Permalink to &quot;市场与融资流动性 Brunnermeier–Pedersen&quot;">​</a></h1><div class="epigraph"><p>做市要占保证金；融资一紧，市场流动性枯竭，保证金再升——流动性螺旋可以自我实现。</p><footer>—— Brunnermeier and Pedersen, Market Liquidity and Funding Liquidity, Review of Financial Studies, 2009</footer></div><p><a href="/econ/intermediary-asset-pricing">上一课</a>的约束是专家净值相对资产规模。本课缺口换成<strong>保证金</strong>：持有（或做市）一单位风险要占用融资，haircut 随波动与不利价格内生。市场流动性（价差、冲击成本）与融资流动性（借钱的难易）互馈。不重写 He–Krishnamurthy 的激励约束形式，不估计 TED 或 VIX。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>接口课把 \\(\\lambda\\) 与价差标成不利选择对象。Brunnermeier 与 Pedersen（2009）给出另一来源：即使信息对称，投机者/做市商的资本与保证金要求也能制造流动性。他们提供市场流动性，但每单位头寸占用融资；价格波动升 → 保证金升 → 融资流动性降 → 被迫减持 → 市场流动性再降。螺旋有两条：保证金螺旋与损失螺旋（与上一课净值放大同族）。缺口是把「流动性」拆成市场端与融资端，并允许它们在均衡里互相决定。</p><p>与 Glosten–Milgrom 并列：那边是逆向选择保险；这边是资本与抵押。危机里两者一起紧，理论要能分开通道。</p><p><span class="marginnote">术语翻译：haircut（折扣率）就是借钱时押品要「打折」的幅度。拿 100 元市价的债券去抵押，haircut=10% 只能借到 90 元；haircut 升到 30%，同样的券只借得到 70 元——差额得自己掏资本垫上，可持头寸的杠杆上限随之收缩。</span></p><p><span class="marginnote">Brunnermeier and Pedersen, <em>RFS</em> 22(6), 2009。保证金取 VaR 型：波动或不利尾部越大，haircut 越高。内生波动使乘数可以大于一。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>投机者效用或中介利润，受资本与保证金约束。市场流动性用反需求斜率或价差度量——本栏仍是均衡对象，不是盘口回归。融资流动性用保证金率与融资利率度量。均衡：给定保证金规则，价格与流动性出清；保证金规则又依赖均衡波动。多重均衡或陡峭的非线性：同一基本面，紧与松两套流动性。</p>',10)),(n(),s(d,null,{default:a(()=>[B(E,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20VOL%5B%22%E6%B3%A2%E5%8A%A8%E5%8D%87%22%5D%20--%3E%20MARG%5B%22%E4%BF%9D%E8%AF%81%E9%87%91%E5%8D%87%22%5D%0A%20%20MARG%20--%3E%20FUND%5B%22%E8%9E%8D%E8%B5%84%E6%B5%81%E5%8A%A8%E6%80%A7%E9%99%8D%22%5D%0A%20%20FUND%20--%3E%20SELL%5B%22%E5%87%8F%E6%8C%81%20%2F%20%E5%81%9C%E6%AD%A2%E5%81%9A%E5%B8%82%22%5D%0A%20%20SELL%20--%3E%20MKT%5B%22%E5%B8%82%E5%9C%BA%E6%B5%81%E5%8A%A8%E6%80%A7%E9%99%8D%22%5D%0A%20%20MKT%20--%3E%20VOL%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[i(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=r("p",null,"不要把螺旋画成限价簿撤单 cascade 的微观过程。撤单是协议；本课是约束与 haircut 的均衡映射。量化栏可以测量螺旋的订单流足迹，本课不写足迹。",-1)),e[4]||(e[4]=r("h2",{id:"机制",tabindex:"-1"},[i("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[5]||(e[5]=r("p",null,"机制是占用稀缺的风险资本。提供流动性是一种杠杆头寸，融资条款把杠杆上限写成价格波动的函数，于是流动性供给的边际成本内生。家庭或长期投资者若不能立刻填上做市空缺（慢资本），短期价格由受约束的边际决定——与 He–Krishnamurthy 同一精神，状态从净值换成保证金规则。信息对称时仍可以发生：波动可以来自公共冲击，不必来自知情单。",-1)),(n(),s(d,null,{default:a(()=>[B(E,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20LR%0A%20%20subgraph%20MG%5B%22%E4%BF%9D%E8%AF%81%E9%87%91%E8%9E%BA%E6%97%8B%22%5D%0A%20%20%20%20A%5B%22%E6%B3%A2%E5%8A%A8%E5%8D%87%22%5D%20--%3E%20B%5B%22haircut%20%E5%8D%87%22%5D%0A%20%20%20%20B%20--%3E%20C%5B%22%E6%96%B0%E5%A4%B4%E5%AF%B8%E5%8D%A0%E7%94%A8%E8%B5%84%E6%9C%AC%E6%9B%B4%E5%A4%9A%22%5D%0A%20%20%20%20C%20--%3E%20D%5B%22%E6%B5%81%E5%8A%A8%E6%80%A7%E4%BE%9B%E7%BB%99%E9%99%8D%20%E2%86%92%20%E4%BB%B7%E5%B7%AE%E6%89%A9%E5%A4%A7%22%5D%0A%20%20end%0A%20%20subgraph%20LS%5B%22%E6%8D%9F%E5%A4%B1%E8%9E%BA%E6%97%8B%22%5D%0A%20%20%20%20E%5B%22%E4%BB%B7%E6%A0%BC%E4%B8%8B%E8%B7%8C%22%5D%20--%3E%20F%5B%22%E4%BA%A4%E6%98%93%E8%80%85%E5%87%80%E5%80%BC%E7%BC%A9%E6%B0%B4%22%5D%0A%20%20%20%20F%20--%3E%20G%5B%22%E9%A3%8E%E9%99%A9%E6%89%BF%E6%8B%85%E8%83%BD%E5%8A%9B%E9%99%8D%22%5D%0A%20%20%20%20G%20--%3E%20H%5B%22%E8%A2%AB%E8%BF%AB%E6%8A%9B%E5%94%AE%20%E2%86%92%20%E4%BB%B7%E6%A0%BC%E5%86%8D%E8%B7%8C%22%5D%0A%20%20end%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[i(" Loading... ",-1)])]),_:1})),e[6]||(e[6]=t('<p>Kyle 的 \\(\\lambda\\) 在有保证金时会被放大：同样的噪声交易，融资紧时冲击更大。本课不重解 Kyle，只指出乘数作用在已有的逆需求上。</p><p><span class="marginnote">数字实例：haircut=5% 时，100 元资本可支撑约 2000 元头寸（杠杆 20 倍）；haircut 升到 20%，同样 100 元只支撑约 500 元（杠杆 5 倍）。没发生任何亏损，仅折扣率一变，可持头寸就被砍掉四分之三——这是螺旋最容易被人低估的燃料。</span></p><p><span class="marginnote">「飞行至流动性」：对保证金敏感的资产先被抛，安全、可抵押的资产被追逐。下一课 Geanakoplos 把可抵押性写成均衡杠杆；再后课便利收益把安全资产标成特殊支付。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不分解 Amihud 比率，不写危机日期的事件研究。下一课杠杆周期从抵押均衡的另一头进入：杠杆本身是内生产品，悲观与乐观用多少保证金来交易。BP 的保证金规则可以外生给定形式；Geanakoplos 让 haircut 在异质信念下被均衡出来。</p><p><span class="marginnote">常见误区：初学者容易把「市场流动性差」与「融资流动性紧」当成同一句话的两种说法。BP 的要点恰是两个对象：前者是价差与冲击成本（出货的代价），后者是保证金与融资利率（加仓的代价）；平时两者可以背离，危机里才互相点火成螺旋。</span></p><p>后课默认：市场流动性与融资流动性可以互馈成螺旋；保证金把波动写进约束。这与不利选择价差是不同通道。协议层的队列仍不在本栏。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>做市占用保证金；融资紧 → 市场流动性降 → 波动与保证金再升。</li><li>螺旋不需要不对称信息，但可以与之叠加。</li><li>状态是融资条件，不是总量消费。</li><li>出处：Brunnermeier and Pedersen, <em>RFS</em> 2009。</li></ul>',9))])}const P=l(p,[["render",u]]);export{g as __pageData,P as default};
